/* =========================================================
   TIFFINMATE
   PART 3 — RESPONSIVE + RTL RESPONSIVE
========================================================= */


/* =========================================================
   1. LARGE DESKTOP
   1440px AND ABOVE
========================================================= */

@media (min-width: 1440px) {

    .header-container {

        width: min(1440px, 94%);

    }


    .main-navigation {

        gap: 28px;

    }

}


/* =========================================================
   2. DESKTOP
   1200px — 1439px
========================================================= */

@media (min-width: 1200px) and (max-width: 1439px) {

    .header-container {

        width: 94%;

    }


    .main-navigation {

        gap: 20px;

    }


    .nav-link {

        font-size: 13px;

    }


    .site-logo {

        width: 140px;

        flex-basis: 140px;

    }


    .site-logo-image {

        width: 140px;

    }


    .header-actions {

        gap: 6px;

    }


    .header-button {

        min-width: 86px;

        padding-left: 15px;

        padding-right: 15px;

        font-size: 13px;

    }


    .header-control {

        width: 38px;

        height: 38px;

    }

}


/* =========================================================
   3. TABLET / IPAD PRO
   1024px — 1199px
========================================================= */

@media (min-width: 1024px) and (max-width: 1199px) {

    /* -----------------------------------------------------
       HEADER
    ----------------------------------------------------- */

    .site-header {

        height: 76px;

    }


    .header-container {

        width: calc(100% - 48px);

    }


    /* -----------------------------------------------------
       LOGO
    ----------------------------------------------------- */

    .site-logo {

        width: 150px;

        height: 58px;

        flex: 0 0 150px;

    }


    .site-logo-image {

        width: 150px;

        max-height: 56px;

    }


    /* -----------------------------------------------------
       HAMBURGER
    ----------------------------------------------------- */

    .mobile-menu-toggle {

        display: inline-flex;

        width: 42px;

        height: 42px;

        margin-left: auto;

    }


    /* -----------------------------------------------------
       HEADER MENU PANEL
    ----------------------------------------------------- */

    .header-menu {

        position: fixed;

        top: 76px;

        right: 24px;

        width: 400px;

        max-width: calc(100vw - 48px);

        height: auto;

        max-height: calc(100vh - 92px);

        padding: 22px;

        display: flex;

        flex-direction: column;

        align-items: stretch;

        gap: 18px;

        overflow-y: auto;

        background: var(--card-background);

        border:
            1px solid var(--border-color);

        border-radius: 14px;

        box-shadow:
            0 20px 55px
            rgba(56, 32, 82, 0.16);

        opacity: 0;

        visibility: hidden;

        pointer-events: none;

        transform:
            translateY(-10px);

        transition:
            opacity var(--transition),
            visibility var(--transition),
            transform var(--transition);

    }


    .header-menu.mobile-menu-open {

        opacity: 1;

        visibility: visible;

        pointer-events: auto;

        transform:
            translateY(0);

    }


    /* -----------------------------------------------------
       MAIN NAVIGATION
    ----------------------------------------------------- */

    .main-navigation {

        position: static;

        left: auto;

        top: auto;

        transform: none;

        width: 100%;

        display: flex;

        flex-direction: column;

        align-items: stretch;

        justify-content: flex-start;

        gap: 4px;

        white-space: normal;

    }


    .nav-link {

        width: 100%;

        height: 46px;

        padding: 0 14px;

        justify-content: flex-start;

        border-radius: 8px;

        font-size: 14px;

    }


    .nav-link::after {

        display: none;

    }


    .nav-link:hover {

        background: var(--primary-light);

    }


    /* -----------------------------------------------------
       HOME DROPDOWN
    ----------------------------------------------------- */

    .nav-dropdown {

        width: 100%;

        height: auto;

        display: block;

    }


    .nav-dropdown-toggle {

        width: 100%;

        justify-content: space-between;

    }


    .nav-dropdown-menu {

        position: static;

        width: 100%;

        min-width: 0;

        margin-top: 3px;

        padding: 4px;

        border: 0;

        border-radius: 8px;

        box-shadow: none;

        background: var(--primary-light);

        opacity: 1;

        visibility: visible;

        pointer-events: auto;

        transform: none;

        display: none;

    }


    .nav-dropdown.dropdown-open
    .nav-dropdown-menu {

        display: block;

    }


    .nav-dropdown:hover
    .nav-dropdown-menu {

        display: none;

        transform: none;

    }


    .nav-dropdown.dropdown-open:hover
    .nav-dropdown-menu {

        display: block;

    }


    .dropdown-item {

        min-height: 42px;

        padding: 0 15px;

        font-size: 13px;

    }


    /* -----------------------------------------------------
       HEADER ACTIONS
    ----------------------------------------------------- */

    .header-actions {

        width: 100%;

        margin: 0;

        padding-top: 18px;

        display: grid;

        grid-template-columns:
            1fr 1fr;

        gap: 8px;

        border-top:
            1px solid var(--border-color);

    }


    .header-control {

        width: 100%;

        height: 42px;

        flex: none;

    }


    .header-button {

        width: 100%;

        min-width: 0;

        height: 42px;

    }

}


