/* =========================================================
   9. RTL — DESKTOP
   1200px AND ABOVE

   LTR:
   LOGO | CENTER MENU | ACTIONS

   RTL:
   ACTIONS | CENTER MENU | LOGO

   Only RTL is changed.
========================================================= */

@media (min-width: 1200px) {

    html[dir="rtl"] .site-header {

        direction: rtl;

    }


    html[dir="rtl"] .header-container {

        direction: rtl;

        flex-direction: row;

    }


    /* -----------------------------------------------------
       LOGO → RIGHT
    ----------------------------------------------------- */

    html[dir="rtl"] .site-logo {

        order: 3;

        margin-left: 0;

        margin-right: 0;

        justify-content: flex-end;

    }


    /* -----------------------------------------------------
       MENU → CENTER
    ----------------------------------------------------- */

    html[dir="rtl"] .header-menu {

        order: 2;

        direction: rtl;

        margin: 0;

    }


    html[dir="rtl"] .main-navigation {

        direction: rtl;

        left: 50%;

        right: auto;

        flex-direction: row-reverse;

        transform:
            translate(-50%, -50%);

    }


    /* -----------------------------------------------------
       ACTIONS → LEFT
    ----------------------------------------------------- */

    html[dir="rtl"] .header-actions {

        order: 1;

        margin-left: auto;

        margin-right: 0;

        direction: rtl;

        flex-direction: row-reverse;

        justify-content: flex-start;

    }


    /* -----------------------------------------------------
       RTL ACTION ORDER

       Left → Dashboard | Login | Dark | RTL
    ----------------------------------------------------- */

    html[dir="rtl"] .dashboard-button {

        order: 4;

    }


    html[dir="rtl"] .login-button {

        order: 3;

    }


    html[dir="rtl"] .dark-control {

        order: 2;

    }


    html[dir="rtl"] .rtl-control {

        order: 1;

    }


    /* -----------------------------------------------------
       NAV TEXT
    ----------------------------------------------------- */

    html[dir="rtl"] .nav-link {

        direction: rtl;

        text-align: right;

    }


    /* -----------------------------------------------------
       DROPDOWN
    ----------------------------------------------------- */

    html[dir="rtl"] .nav-dropdown {

        direction: rtl;

    }


    html[dir="rtl"] .nav-dropdown-menu {

        left: auto;

        right: 50%;

        transform:
            translate(50%, 8px);

    }


    html[dir="rtl"]
    .nav-dropdown:hover
    .nav-dropdown-menu {

        transform:
            translate(50%, 0);

    }


    html[dir="rtl"] .dropdown-item {

        text-align: right;

        justify-content: flex-start;

    }


    /* -----------------------------------------------------
       RTL ARROW
    ----------------------------------------------------- */

    html[dir="rtl"] .dropdown-arrow {

        transform: rotate(0deg);

    }


