/* =========================================================
   1. RTL DESKTOP
   1200px AND ABOVE
========================================================= */

@media (min-width: 1200px) {

    /* -----------------------------------------------------
       HEADER
    ----------------------------------------------------- */

    html[dir="rtl"] .site-header {

        direction: rtl;

    }


    html[dir="rtl"] .header-container {

        direction: rtl;

        position: relative;

        display: flex;

        flex-direction: row;

    }


    /* -----------------------------------------------------
       LOGO
       FORCE LOGO TO RIGHT
    ----------------------------------------------------- */

    html[dir="rtl"] .site-logo {

        position: absolute;

        right: 0;

        left: auto;

        top: 50%;

        transform: translateY(-50%);

        width: 150px;

        margin: 0;

        z-index: 10;

        justify-content: flex-end;

    }


    html[dir="rtl"] .site-logo:hover {

        transform:
            translateY(-50%)
            scale(1.025);

    }


    /* -----------------------------------------------------
       HEADER MENU
    ----------------------------------------------------- */

    html[dir="rtl"] .header-menu {

        width: 100%;

        height: 100%;

        margin: 0;

        padding: 0;

        direction: rtl;

    }


    /* -----------------------------------------------------
       NAVIGATION
       KEEP EXACTLY CENTERED
    ----------------------------------------------------- */

    html[dir="rtl"] .main-navigation {

        position: absolute;

        left: 50%;

        right: auto;

        top: 50%;

        transform:
            translate(-50%, -50%);

        display: flex;

        flex-direction: row;

        align-items: center;

        justify-content: center;

        direction: rtl;

        gap: var(--nav-gap);

        margin: 0;

        padding: 0;

    }


    /* -----------------------------------------------------
       NAVIGATION TEXT
    ----------------------------------------------------- */

    html[dir="rtl"] .nav-link {

        direction: rtl;

        text-align: right;

    }


    /* -----------------------------------------------------
       ACTIONS
       FORCE ACTIONS TO LEFT
    ----------------------------------------------------- */

    html[dir="rtl"] .header-actions {

        position: absolute;

        left: 0;

        right: auto;

        top: 50%;

        transform: translateY(-50%);

        margin: 0;

        padding: 0;

        display: flex;

        align-items: center;

        justify-content: flex-start;

        flex-direction: row;

        direction: rtl;

        gap: var(--action-gap);

        z-index: 10;

    }


    /* -----------------------------------------------------
       IMPORTANT:
       Do NOT use order here.
       The controls simply stay together on LEFT.
    ----------------------------------------------------- */

    html[dir="rtl"] .header-actions > * {

        order: initial;

    }


    /* -----------------------------------------------------
       DROPDOWN
    ----------------------------------------------------- */

    html[dir="rtl"] .nav-dropdown {

        direction: rtl;

    }


    html[dir="rtl"] .nav-dropdown-menu {

        left: auto;

        right: 50%;

        transform:
            translate(50%, 8px);

    }


    html[dir="rtl"]
    .nav-dropdown:hover
    .nav-dropdown-menu {

        transform:
            translate(50%, 0);

    }


    /* -----------------------------------------------------
       DROPDOWN ITEM
    ----------------------------------------------------- */

    html[dir="rtl"] .dropdown-item {

        direction: rtl;

        text-align: right;

        justify-content: flex-start;

    }


    /* -----------------------------------------------------
       DROPDOWN ARROW
    ----------------------------------------------------- */

    html[dir="rtl"] .dropdown-arrow {

        transform: rotate(0deg);

    }


    html[dir="rtl"]
    .nav-dropdown:hover
    .dropdown-arrow {

        transform: rotate(180deg);

    }

}


