/* =========================================================
   PROCESS STEPS
========================================================= */

.home1-how-it-works-steps {
    display: grid;
    grid-template-columns: repeat(4, minmax(0, 1fr));

    gap: 20px;

    position: relative;
}


/* =========================================================
   STEP CARD
========================================================= */

.home1-how-step {
    position: relative;

    min-width: 0;
    padding: 0 4px 0 0;
}


/* =========================================================
   STEP NUMBER + CONNECTOR
========================================================= */

.home1-how-step-top {
    position: relative;

    display: flex;
    align-items: center;

    min-height: 40px;
    margin-bottom: 22px;
}

.home1-how-step-number {
    position: relative;
    z-index: 2;

    display: inline-flex;
    align-items: center;
    justify-content: center;

    width: 42px;
    height: 42px;

    flex: 0 0 42px;

    border: 1px solid var(--primary-color);
    border-radius: 50%;

    background: var(--section-background);

    font-family: var(--font-family);
    font-size: 12px;
    font-weight: 700;
    line-height: 1;

    color: var(--primary-color);
}

.home1-how-step-line {
    position: absolute;

    top: 50%;
    left: 42px;
    right: -20px;

    height: 1px;

    background: var(--border-color);

    transform: translateY(-50%);
}

.home1-how-step-line-last {
    display: none;
}


/* =========================================================
   STEP ICON
========================================================= */

.home1-how-step-icon {
    display: inline-flex;
    align-items: center;
    justify-content: center;

    width: 58px;
    height: 58px;

    margin-bottom: 20px;

    border-radius: 14px;

    background: var(--primary-light);

    color: var(--primary-color);

    transition:
        background 0.25s ease,
        color 0.25s ease,
        transform 0.25s ease;
}

.home1-how-step-icon svg {
    width: 27px;
    height: 27px;

    fill: none;
    stroke: currentColor;
    stroke-width: 1.6;
    stroke-linecap: round;
    stroke-linejoin: round;
}

.home1-how-step:hover .home1-how-step-icon {
    background: var(--primary-color);
    color: #FFFFFF;

    transform: translateY(-3px);
}


/* =========================================================
   STEP CONTENT
========================================================= */

.home1-how-step-label {
    display: block;

    margin-bottom: 8px;

    font-family: var(--font-family);
    font-size: 10px;
    font-weight: 700;
    line-height: 1.3;
    letter-spacing: 1px;
    text-transform: uppercase;

    color: var(--primary-color);
}

.home1-how-step-content h3 {
    margin: 0;

    font-family: var(--font-family);
    font-size: 20px;
    font-weight: 700;
    line-height: 1.3;
    letter-spacing: -0.25px;

    color: var(--heading-color);
}

.home1-how-step-content p {
    max-width: 285px;

    margin: 10px 0 0;

    font-family: var(--font-family);
    font-size: 13px;
    font-weight: 400;
    line-height: 1.7;

    color: var(--muted-text);
}


/* =========================================================
   HIGHLIGHTS
========================================================= */

.home1-how-it-works-highlights {
    display: grid;
    grid-template-columns: 1fr auto 1fr auto 1fr;

    align-items: center;

    gap: 22px;

    margin-top: 58px;
    padding: 22px 24px;

    border: 1px solid var(--border-color);
    border-radius: 12px;

    background: var(--page-background);
}

.home1-how-highlight {
    display: flex;
    align-items: center;
    gap: 12px;

    min-width: 0;
}

.home1-how-highlight-icon {
    display: inline-flex;
    align-items: center;
    justify-content: center;

    width: 38px;
    height: 38px;

    flex: 0 0 38px;

    border-radius: 50%;

    background: var(--primary-light);

    color: var(--primary-color);
}

.home1-how-highlight-icon svg {
    width: 18px;
    height: 18px;

    fill: none;
    stroke: currentColor;
    stroke-width: 1.7;
    stroke-linecap: round;
    stroke-linejoin: round;
}

.home1-how-highlight div {
    display: flex;
    flex-direction: column;
    gap: 3px;

    min-width: 0;
}

.home1-how-highlight strong {
    font-family: var(--font-family);
    font-size: 12px;
    font-weight: 700;
    line-height: 1.3;

    color: var(--heading-color);
}

.home1-how-highlight div span {
    font-family: var(--font-family);
    font-size: 11px;
    font-weight: 400;
    line-height: 1.4;

    color: var(--muted-text);
}

.home1-how-highlight-divider {
    width: 1px;
    height: 34px;

    background: var(--border-color);
}


/* =========================================================
   CTA
========================================================= */

.home1-how-it-works-cta {
    display: flex;
    align-items: center;
    justify-content: space-between;

    gap: 30px;

    margin-top: 28px;
    padding: 28px 30px;

    border-radius: 14px;

    background: var(--primary-dark);

    color: #FFFFFF;
}

.home1-how-cta-content {
    min-width: 0;
}

.home1-how-cta-eyebrow {
    display: block;

    margin-bottom: 7px;

    font-family: var(--font-family);
    font-size: 10px;
    font-weight: 700;
    line-height: 1.3;
    letter-spacing: 1.2px;
    text-transform: uppercase;

    color: rgba(255, 255, 255, 0.68);
}

.home1-how-cta-content h3 {
    max-width: 650px;

    margin: 0;

    font-family: var(--font-family);
    font-size: 22px;
    font-weight: 700;
    line-height: 1.35;
    letter-spacing: -0.3px;

    color: #FFFFFF;
}


/* =========================================================
   CTA BUTTON
========================================================= */

.home1-how-cta-button {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 9px;

    min-width: 150px;
    height: 44px;

    flex: 0 0 auto;

    padding: 0 17px;

    border: 1px solid rgba(255, 255, 255, 0.22);
    border-radius: var(--button-radius);

    background: #FFFFFF;

    font-family: var(--font-family);
    font-size: 13px;
    font-weight: 600;
    line-height: 1;
    text-decoration: none;

    color: var(--primary-dark);

    transition:
        background 0.25s ease,
        color 0.25s ease,
        transform 0.25s ease,
        box-shadow 0.25s ease;
}

.home1-how-cta-button svg {
    width: 16px;
    height: 16px;

    fill: none;
    stroke: currentColor;
    stroke-width: 1.8;
    stroke-linecap: round;
    stroke-linejoin: round;

    transition: transform 0.25s ease;
}

.home1-how-cta-button:hover {
    background: var(--primary-light);
    color: var(--primary-dark);

    transform: translateY(-2px);

    box-shadow:
        0 8px 20px rgba(0, 0, 0, 0.15);
}

.home1-how-cta-button:hover svg {
    transform: translateX(2px);
}


/* =========================================================
   DARK MODE
========================================================= */

body.dark-mode .home1-how-step-number {
    background: var(--section-background);
}

body.dark-mode .home1-how-it-works-highlights {
    background: var(--card-background);
}

body.dark-mode .home1-how-it-works-cta {
    background: #241833;
}

body.dark-mode .home1-how-cta-button {
    background: #FFFFFF;
    color: var(--primary-dark);
}


/* =========================================================
   FOCUS
========================================================= */

.home1-how-cta-button:focus-visible {
    outline: 2px solid var(--primary-color);
    outline-offset: 3px;
}


/* =========================================================
   REDUCED MOTION
========================================================= */

@media (prefers-reduced-motion: reduce) {

    .home1-how-step-icon,
    .home1-how-cta-button,
    .home1-how-cta-button svg {
        transition: none;
    }

    .home1-how-step:hover .home1-how-step-icon {
        transform: none;
    }

    .home1-how-cta-button:hover {
        transform: none;
    }
}

