========================================================= */


/* =========================================================
   ABOUT SECTION
========================================================= */

.chef-about-section {
    position: relative;
    padding: 100px 0;
    background: var(--section-background);
    overflow: hidden;
}

.chef-about-container {
    width: min(1240px, calc(100% - 48px));
    margin: 0 auto;
}


/* =========================================================
   COMMON SECTION HEADER
========================================================= */

.chef-about-heading {
    max-width: 760px;
    margin: 0 auto 52px;
    text-align: center;
}

.chef-section-eyebrow {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 9px;

    margin-bottom: 13px;

    color: var(--primary-color);

    font-family: var(--font-family);
    font-size: 11px;
    font-weight: 700;
    letter-spacing: 0.14em;
    line-height: 1.4;
}

.chef-section-eyebrow::before,
.chef-section-eyebrow::after {
    content: "";
    width: 25px;
    height: 2px;

    background: var(--primary-color);
    border-radius: 999px;
}

.chef-section-title {
    margin: 0;

    color: var(--heading-color);

    font-family: var(--font-family);
    font-size: clamp(32px, 3.2vw, 44px);
    font-weight: 800;
    letter-spacing: -0.035em;
    line-height: 1.15;
}

.chef-section-title span {
    color: var(--primary-color);
}

.chef-section-description {
    max-width: 650px;
    margin: 16px auto 0;

    color: var(--muted-text);

    font-family: var(--font-family);
    font-size: 14px;
    font-weight: 400;
    line-height: 1.8;
}


/* =========================================================
   ABOUT LAYOUT
========================================================= */

.chef-about-layout {
    display: grid;
    grid-template-columns: minmax(0, 1.08fr) minmax(360px, 0.92fr);
    gap: 28px;
    align-items: stretch;
}


/* =========================================================
   ABOUT STORY
========================================================= */

.chef-about-story {
    padding: 42px;

    background: var(--card-background);

    border: 1px solid var(--border-color);
    border-radius: 16px;

    box-shadow:
        0 12px 35px rgba(56, 32, 82, 0.045);
}

.chef-about-story-header {
    margin-bottom: 22px;
}

.chef-about-story-label {
    display: inline-block;
    margin-bottom: 9px;

    color: var(--primary-color);

    font-family: var(--font-family);
    font-size: 10px;
    font-weight: 700;
    letter-spacing: 0.12em;
    line-height: 1.4;
}

.chef-about-story-header h3 {
    margin: 0;

    color: var(--heading-color);

    font-family: var(--font-family);
    font-size: 27px;
    font-weight: 750;
    letter-spacing: -0.025em;
    line-height: 1.3;
}

.chef-about-story-content {
    display: flex;
    flex-direction: column;
    gap: 14px;
}

.chef-about-story-content p {
    margin: 0;

    color: var(--muted-text);

    font-family: var(--font-family);
    font-size: 13px;
    font-weight: 400;
    line-height: 1.85;
}


/* =========================================================
   CHEF SIGNATURE
========================================================= */

.chef-about-signature {
    display: flex;
    align-items: center;
    gap: 13px;

    margin-top: 28px;
    padding-top: 22px;

    border-top: 1px solid var(--border-color);
}

.chef-about-signature-line {
    width: 3px;
    height: 42px;

    flex: 0 0 auto;

    background: var(--primary-color);
    border-radius: 999px;
}

.chef-about-signature-content {
    display: flex;
    flex-direction: column;
    gap: 4px;
}

.chef-about-signature-content strong {
    color: var(--heading-color);

    font-family: var(--font-family);
    font-size: 14px;
    font-weight: 700;
}

.chef-about-signature-content span {
    color: var(--muted-text);

    font-family: var(--font-family);
    font-size: 10px;
    font-weight: 500;
}


/* =========================================================
   FOOD PHILOSOPHY
========================================================= */

.chef-food-philosophy-card {
    position: relative;

    padding: 38px;

    background:
        linear-gradient(
            145deg,
            var(--primary-light),
            var(--card-background)
        );

    border: 1px solid var(--border-color);
    border-radius: 16px;

    overflow: hidden;
}

.chef-food-philosophy-card::after {
    content: "";

    position: absolute;
    right: -70px;
    bottom: -80px;

    width: 220px;
    height: 220px;

    border: 1px solid rgba(108, 74, 182, 0.10);
    border-radius: 50%;

    pointer-events: none;
}

.chef-food-philosophy-icon {
    display: inline-flex;
    align-items: center;
    justify-content: center;

    width: 54px;
    height: 54px;

    color: var(--primary-color);
    background: var(--card-background);

    border: 1px solid var(--border-color);
    border-radius: 12px;

    box-shadow:
        0 8px 20px rgba(56, 32, 82, 0.05);
}

.chef-food-philosophy-eyebrow {
    display: block;

    margin-top: 24px;

    color: var(--primary-color);

    font-family: var(--font-family);
    font-size: 10px;
    font-weight: 700;
    letter-spacing: 0.12em;
    line-height: 1.4;
}

.chef-food-philosophy-card h3 {
    position: relative;
    z-index: 1;

    max-width: 430px;
    margin: 10px 0 14px;

    color: var(--heading-color);

    font-family: var(--font-family);
    font-size: 25px;
    font-weight: 750;
    letter-spacing: -0.025em;
    line-height: 1.35;
}

.chef-food-philosophy-card > p {
    position: relative;
    z-index: 1;

    margin: 0;

    color: var(--muted-text);

    font-family: var(--font-family);
    font-size: 12px;
    font-weight: 400;
    line-height: 1.8;
}


/* =========================================================
   PHILOSOPHY POINTS
========================================================= */

.chef-philosophy-points {
    position: relative;
    z-index: 1;

    display: flex;
    flex-direction: column;
    gap: 13px;

    margin-top: 27px;
    padding-top: 22px;

    border-top: 1px solid var(--border-color);
}

.chef-philosophy-point {
    display: flex;
    align-items: flex-start;
    gap: 13px;
}

.chef-philosophy-point-number {
    display: inline-flex;
    align-items: center;
    justify-content: center;

    width: 32px;
    height: 32px;

    flex: 0 0 auto;

    color: var(--primary-color);
    background: var(--card-background);

    border: 1px solid var(--border-color);
    border-radius: 7px;

    font-family: var(--font-family);
    font-size: 9px;
    font-weight: 700;
}

.chef-philosophy-point > div {
    display: flex;
    flex-direction: column;
    gap: 3px;
    padding-top: 1px;
}

.chef-philosophy-point strong {
    color: var(--heading-color);

    font-family: var(--font-family);
    font-size: 12px;
    font-weight: 700;
}

.chef-philosophy-point div span {
    color: var(--muted-text);

    font-family: var(--font-family);
    font-size: 10px;
    font-weight: 400;
    line-height: 1.5;
}


/* =========================================================
   SPECIALITIES SECTION
========================================================= */

.chef-specialities-section {
    position: relative;
    padding: 100px 0;

    background: var(--page-background);
    overflow: hidden;
}

.chef-specialities-container {
    width: min(1240px, calc(100% - 48px));
    margin: 0 auto;
}


/* =========================================================
   SPECIALITIES HEADER
========================================================= */

.chef-specialities-header {
    display: flex;
    align-items: flex-end;
    justify-content: space-between;
    gap: 40px;

    margin-bottom: 42px;
}

.chef-specialities-heading {
    flex: 1;
}

.chef-specialities-heading .chef-section-eyebrow {
    justify-content: flex-start;
}

.chef-specialities-description {
    max-width: 390px;
    margin: 0;

    color: var(--muted-text);

    font-family: var(--font-family);
    font-size: 13px;
    font-weight: 400;
    line-height: 1.8;
}


/* =========================================================
   SPECIALITY GRID
========================================================= */

.chef-specialities-grid {
    display: grid;
    grid-template-columns: repeat(4, minmax(0, 1fr));
    gap: 16px;
}


/* =========================================================
   SPECIALITY CARD
========================================================= */

.chef-speciality-card {
    position: relative;

    min-height: 250px;
    padding: 28px 25px;

    background: var(--card-background);

    border: 1px solid var(--border-color);
    border-radius: 14px;

    overflow: hidden;

    transition:
        transform 0.3s ease,
        border-color 0.3s ease,
        box-shadow 0.3s ease;
}

.chef-speciality-card:hover {
    transform: translateY(-5px);

    border-color: rgba(108, 74, 182, 0.32);

    box-shadow:
        0 15px 32px rgba(56, 32, 82, 0.07);
}


/* =========================================================
   SPECIALITY NUMBER
========================================================= */

.chef-speciality-number {
    position: absolute;
    top: 18px;
    right: 20px;

    color: var(--border-color);

    font-family: var(--font-family);
    font-size: 12px;
    font-weight: 700;
    line-height: 1;
}


/* =========================================================
   SPECIALITY ICON
========================================================= */

.chef-speciality-icon {
    display: inline-flex;
    align-items: center;
    justify-content: center;

    width: 54px;
    height: 54px;

    color: var(--primary-color);
    background: var(--primary-light);

    border-radius: 12px;
}

.chef-speciality-icon svg {
    flex: 0 0 auto;
}


/* =========================================================
   SPECIALITY CONTENT
========================================================= */

.chef-speciality-content {
    margin-top: 27px;
}

.chef-speciality-content h3 {
    margin: 0;

    color: var(--heading-color);

    font-family: var(--font-family);
    font-size: 16px;
    font-weight: 700;
    line-height: 1.35;
}

.chef-speciality-content p {
    margin: 9px 0 0;

    color: var(--muted-text);

    font-family: var(--font-family);
    font-size: 11px;
    font-weight: 400;
    line-height: 1.7;
}


/* =========================================================
   SPECIALITY TAGS
========================================================= */

.chef-speciality-tags-wrapper {
    display: flex;
    align-items: center;
    flex-wrap: wrap;
    gap: 16px;

    margin-top: 27px;
    padding: 19px 22px;

    background: var(--card-background);

    border: 1px solid var(--border-color);
    border-radius: 12px;
}

.chef-speciality-tags-label {
    color: var(--muted-text);

    font-family: var(--font-family);
    font-size: 9px;
    font-weight: 700;
    letter-spacing: 0.1em;
    white-space: nowrap;
}

.chef-speciality-tags {
    display: flex;
    align-items: center;
    flex-wrap: wrap;
    gap: 7px;
}

.chef-speciality-tags span {
    display: inline-flex;
    align-items: center;
    justify-content: center;

    min-height: 28px;
    padding: 0 10px;

    color: var(--primary-dark);
    background: var(--primary-light);

    border-radius: 6px;

    font-family: var(--font-family);
    font-size: 9px;
    font-weight: 600;
    line-height: 1;
}


/* =========================================================
   CHEF STATS SECTION
========================================================= */

.chef-stats-section {
    position: relative;

    padding: 0;

    background: var(--section-background);
}

.chef-stats-container {
    width: min(1240px, calc(100% - 48px));
    margin: 0 auto;
}

.chef-stats-grid {
    display: grid;
    grid-template-columns: repeat(4, minmax(0, 1fr));

    border-top: 1px solid var(--border-color);
    border-bottom: 1px solid var(--border-color);
}


/* =========================================================
   STAT ITEM
========================================================= */

.chef-stat-item {
    display: flex;
    align-items: center;
    gap: 15px;

    min-height: 125px;
    padding: 24px 28px;

    border-right: 1px solid var(--border-color);
}

.chef-stat-item:last-child {
    border-right: none;
}

.chef-stat-icon {
    display: inline-flex;
    align-items: center;
    justify-content: center;

    width: 48px;
    height: 48px;

    flex: 0 0 auto;

    color: var(--primary-color);
    background: var(--primary-light);

    border-radius: 10px;
}

.chef-stat-content {
    display: flex;
    flex-direction: column;
    gap: 5px;
}

.chef-stat-value {
    color: var(--heading-color);

    font-family: var(--font-family);
    font-size: 21px;
    font-weight: 800;
    line-height: 1.1;
}

.chef-stat-content span {
    color: var(--muted-text);

    font-family: var(--font-family);
    font-size: 10px;
    font-weight: 500;
    line-height: 1.4;
}


/* =========================================================
   DARK MODE
========================================================= */

body.dark-mode .chef-about-story,
body.dark-mode .chef-food-philosophy-card,
body.dark-mode .chef-speciality-card,
body.dark-mode .chef-speciality-tags-wrapper {
    box-shadow:
        0 12px 35px rgba(0, 0, 0, 0.16);
}

body.dark-mode .chef-food-philosophy-card {
    background:
        linear-gradient(
            145deg,
            var(--primary-light),
            var(--card-background)
        );
}

body.dark-mode .chef-speciality-tags span {
    color: #E9DFFF;
    background: var(--primary-light);
}


/* =========================================================
   FOCUS STATES
========================================================= */

.chef-speciality-card:focus-within {
    border-color: var(--primary-color);
}


/* =========================================================
   SELECTION
========================================================= */

.chef-about-section ::selection,
.chef-specialities-section ::selection,
.chef-stats-section ::selection {
    color: #FFFFFF;
    background: var(--primary-color);
}



/* =========================================================
   SECTION 5 — RESPONSIVE
   POPULAR HOMEMADE MEALS
========================================================= */


/* =========================================================
   LARGE DESKTOP
   1440px+
========================================================= */

@media (min-width: 1440px) {

    .chef-meals-container {
        width: min(1280px, calc(100% - 80px));
