/* =========================================================
   SECTION 7 — CHEF'S MENU
========================================================= */

.chef-menu-section {
    position: relative;
    width: 100%;
    padding: 100px 0;
    background: var(--page-background);
    overflow: hidden;
}

.chef-menu-container {
    width: min(1280px, calc(100% - 48px));
    margin: 0 auto;
}


/* =========================================================
   SECTION HEADER
========================================================= */

.chef-menu-header {
    display: flex;
    align-items: flex-end;
    justify-content: space-between;
    gap: 40px;
    margin-bottom: 38px;
}

.chef-menu-heading {
    max-width: 760px;
}

.chef-menu-chef-note {
    flex-shrink: 0;

    display: inline-flex;
    align-items: center;
    gap: 9px;

    min-height: 40px;
    padding: 0 15px;

    border: 1px solid var(--border-color);
    border-radius: 8px;

    background: var(--card-background);
    color: var(--muted-text);

    font-family: var(--font-family);
    font-size: 12px;
    font-weight: 600;
    line-height: 1;
}

.chef-menu-chef-note-dot {
    width: 7px;
    height: 7px;
    flex-shrink: 0;

    border-radius: 50%;
    background: #3E9B61;

    box-shadow:
        0 0 0 4px rgba(62, 155, 97, 0.10);
}


/* =========================================================
   CATEGORY TABS
========================================================= */

.chef-menu-tabs {
    display: flex;
    align-items: center;
    gap: 8px;

    width: 100%;
    margin-bottom: 22px;
    padding: 6px;

    border: 1px solid var(--border-color);
    border-radius: 10px;

    background: var(--card-background);

    overflow-x: auto;
    scrollbar-width: none;
}

.chef-menu-tabs::-webkit-scrollbar {
    display: none;
}

.chef-menu-tab {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 7px;

    min-height: 40px;
    padding: 0 18px;

    border: 1px solid transparent;
    border-radius: 7px;

    background: transparent;
    color: var(--muted-text);

    font-family: var(--font-family);
    font-size: 13px;
    font-weight: 600;
    line-height: 1;
    white-space: nowrap;

    cursor: pointer;

    transition:
        color 0.2s ease,
        background-color 0.2s ease,
        border-color 0.2s ease;
}

.chef-menu-tab:hover {
    color: var(--primary-color);
    background: var(--primary-light);
}

.chef-menu-tab.active {
    border-color: var(--primary-color);
    background: var(--primary-color);
    color: #FFFFFF;
}

.chef-menu-tab:focus-visible {
    outline: 2px solid var(--primary-color);
    outline-offset: 2px;
}

.chef-menu-tab-icon {
    display: inline-flex;
    align-items: center;
    justify-content: center;
}


/* =========================================================
   MENU TOOLBAR
========================================================= */

.chef-menu-toolbar {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 20px;

    margin-bottom: 22px;
}

.chef-menu-result-info {
    display: inline-flex;
    align-items: center;
    gap: 9px;

    color: var(--muted-text);

    font-family: var(--font-family);
    font-size: 12px;
    font-weight: 500;
}

.chef-menu-result-count {
    color: var(--heading-color);
    font-weight: 700;
}

.chef-menu-result-divider {
    color: var(--border-color);
}

.chef-menu-toolbar-actions {
    display: inline-flex;
    align-items: center;
    gap: 9px;
}

.chef-menu-sort-label {
    color: var(--muted-text);

    font-family: var(--font-family);
    font-size: 12px;
    font-weight: 500;
}

.chef-menu-sort {
    min-width: 165px;
    height: 38px;
    padding: 0 32px 0 11px;

    border: 1px solid var(--border-color);
    border-radius: 7px;

    background-color: var(--card-background);
    color: var(--text-color);

    font-family: var(--font-family);
    font-size: 12px;
    font-weight: 550;

    cursor: pointer;

    outline: none;

    transition:
        border-color 0.2s ease,
        box-shadow 0.2s ease;
}

.chef-menu-sort:hover {
    border-color: var(--primary-color);
}

.chef-menu-sort:focus {
    border-color: var(--primary-color);
    box-shadow:
        0 0 0 3px rgba(108, 74, 182, 0.10);
}


/* =========================================================
   MENU GRID
========================================================= */

.chef-menu-grid {
    display: grid;
    grid-template-columns: repeat(4, minmax(0, 1fr));
    gap: 20px;
}


/* =========================================================
   MENU ITEM CARD
========================================================= */

.chef-menu-item {
    position: relative;
    min-width: 0;
    overflow: hidden;

    border: 1px solid var(--border-color);
    border-radius: 13px;

    background: var(--card-background);

    box-shadow:
        0 7px 22px rgba(56, 32, 82, 0.05);

    transition:
        transform 0.28s ease,
        border-color 0.28s ease,
        box-shadow 0.28s ease;
}

.chef-menu-item:hover {
    border-color: rgba(108, 74, 182, 0.35);

    box-shadow:
        0 15px 32px rgba(56, 32, 82, 0.10);

    transform: translateY(-4px);
}

.chef-menu-item.is-hidden {
    display: none;
}


/* =========================================================
   MENU ITEM IMAGE
========================================================= */

.chef-menu-item-image-wrap {
    position: relative;
    width: 100%;
    height: 190px;
    overflow: hidden;

    background: var(--primary-light);
}

.chef-menu-item-image {
    display: block;

    width: 100%;
    height: 100%;

    object-fit: cover;

    transition:
        transform 0.45s ease;
}

.chef-menu-item:hover .chef-menu-item-image {
    transform: scale(1.04);
}


/* =========================================================
   FOOD TYPE BADGE
========================================================= */

.chef-menu-item-type {
    position: absolute;
    top: 12px;
    left: 12px;

    display: inline-flex;
    align-items: center;
    justify-content: center;

    min-height: 23px;
    padding: 0 8px;

    border-radius: 5px;

    background: rgba(255, 255, 255, 0.95);

    font-family: var(--font-family);
    font-size: 9px;
    font-weight: 750;
    letter-spacing: 0.6px;
    line-height: 1;
}

.chef-menu-item-veg {
    color: #2E7D32;
}

.chef-menu-item-nonveg {
    color: #B33A3A;
}


/* =========================================================
   FAVORITE
========================================================= */

.chef-menu-item-favorite {
    position: absolute;
    top: 9px;
    right: 9px;

    display: inline-flex;
    align-items: center;
    justify-content: center;

    width: 36px;
    height: 36px;
    padding: 0;

    border: 1px solid rgba(255, 255, 255, 0.8);
    border-radius: 50%;

    background: rgba(255, 255, 255, 0.94);
    color: #4A4350;

    cursor: pointer;

    box-shadow:
        0 5px 14px rgba(0, 0, 0, 0.08);

    transition:
        color 0.2s ease,
        background-color 0.2s ease,
        border-color 0.2s ease,
        transform 0.2s ease;
}

.chef-menu-item-favorite:hover {
    border-color: var(--primary-color);
    color: var(--primary-color);
    transform: translateY(-2px);
}

.chef-menu-item-favorite[aria-pressed="true"] {
    border-color: var(--primary-color);
    background: var(--primary-color);
    color: #FFFFFF;
}

.chef-menu-item-favorite:focus-visible {
    outline: 2px solid var(--primary-color);
    outline-offset: 3px;
}


/* =========================================================
   MENU ITEM CONTENT
========================================================= */

.chef-menu-item-content {
    padding: 17px 16px 16px;
}


/* =========================================================
   ITEM TITLE + RATING
========================================================= */

.chef-menu-item-top {
    display: flex;
    align-items: flex-start;
    justify-content: space-between;
    gap: 10px;
}

.chef-menu-item-top > div:first-child {
    min-width: 0;
}

.chef-menu-item-top h3 {
    display: -webkit-box;

    overflow: hidden;

    margin: 0;

    color: var(--heading-color);

    font-family: var(--font-family);
    font-size: 16px;
    font-weight: 700;
    line-height: 1.35;

    -webkit-box-orient: vertical;
    -webkit-line-clamp: 2;
}

.chef-menu-item-category {
    display: inline-block;

    margin-top: 5px;

    color: var(--primary-color);

    font-family: var(--font-family);
    font-size: 10px;
    font-weight: 650;
    line-height: 1.3;
    text-transform: uppercase;
    letter-spacing: 0.4px;
}

.chef-menu-item-rating {
    display: inline-flex;
    align-items: center;
    gap: 4px;

    flex-shrink: 0;

    color: var(--heading-color);

    font-family: var(--font-family);
    font-size: 11px;
    font-weight: 650;
    line-height: 1;
}

.chef-menu-item-rating svg {
    color: #E4A11B;
}


/* =========================================================
   DESCRIPTION
========================================================= */

.chef-menu-item-description {
    display: -webkit-box;

    overflow: hidden;

    min-height: 40px;
    margin: 10px 0 11px;

    color: var(--muted-text);

    font-family: var(--font-family);
    font-size: 12px;
    font-weight: 400;
    line-height: 1.65;

    -webkit-box-orient: vertical;
    -webkit-line-clamp: 2;
}


/* =========================================================
   META
========================================================= */

.chef-menu-item-meta {
    display: flex;
    align-items: center;
    flex-wrap: wrap;
    gap: 6px;

    color: var(--muted-text);

    font-family: var(--font-family);
    font-size: 10px;
    font-weight: 550;
    line-height: 1.4;
}


/* =========================================================
   ITEM FOOTER
========================================================= */

.chef-menu-item-footer {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 10px;

    margin-top: 15px;
    padding-top: 13px;

    border-top: 1px solid var(--border-color);
}

.chef-menu-item-price {
    display: flex;
    align-items: baseline;
    gap: 3px;

    flex-shrink: 0;
}

.chef-menu-item-price strong {
    color: var(--heading-color);

    font-family: var(--font-family);
    font-size: 18px;
    font-weight: 750;
    line-height: 1;
}

.chef-menu-item-price span {
    color: var(--muted-text);

    font-family: var(--font-family);
    font-size: 10px;
    font-weight: 500;
}


/* =========================================================
   ADD TO ORDER BUTTON
========================================================= */

.chef-menu-add-btn {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 6px;

    min-height: 34px;
    padding: 0 10px;

    border: 1px solid var(--primary-color);
    border-radius: 6px;

    background: transparent;
    color: var(--primary-color);

    font-family: var(--font-family);
    font-size: 10px;
    font-weight: 650;
    line-height: 1;
    white-space: nowrap;

    cursor: pointer;

    transition:
        color 0.2s ease,
        background-color 0.2s ease,
        transform 0.2s ease;
}

.chef-menu-add-btn svg {
    flex-shrink: 0;

    transition:
        transform 0.2s ease;
}

.chef-menu-add-btn:hover {
    background: var(--primary-color);
    color: #FFFFFF;
    transform: translateY(-1px);
}

.chef-menu-add-btn:hover svg {
    transform: rotate(90deg);
}

.chef-menu-add-btn:focus-visible {
    outline: 2px solid var(--primary-color);
    outline-offset: 3px;
}

.chef-menu-add-btn.added {
    border-color: #3E9B61;
    background: #3E9B61;
    color: #FFFFFF;
}


/* =========================================================
   EMPTY STATE
========================================================= */

.chef-menu-empty {
    display: flex;
    align-items: center;
    flex-direction: column;

    width: 100%;
    padding: 55px 24px;

    border: 1px dashed var(--border-color);
    border-radius: 13px;

    background: var(--card-background);

    text-align: center;
}

.chef-menu-empty[hidden] {
    display: none;
}

.chef-menu-empty-icon {
    display: inline-flex;
    align-items: center;
    justify-content: center;

    width: 58px;
    height: 58px;
    margin-bottom: 15px;

    border-radius: 50%;

    background: var(--primary-light);
    color: var(--primary-color);
}

.chef-menu-empty h3 {
    margin: 0;

    color: var(--heading-color);

    font-family: var(--font-family);
    font-size: 18px;
    font-weight: 700;
    line-height: 1.4;
}

.chef-menu-empty p {
    max-width: 430px;
    margin: 8px 0 0;

    color: var(--muted-text);

    font-family: var(--font-family);
    font-size: 13px;
    font-weight: 400;
    line-height: 1.7;
}


/* =========================================================
   BOTTOM
========================================================= */

.chef-menu-bottom {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 24px;

    margin-top: 32px;
    padding-top: 23px;

    border-top: 1px solid var(--border-color);
}

.chef-menu-bottom-info {
    display: flex;
    align-items: center;
    gap: 12px;
}

.chef-menu-bottom-line {
    display: block;

    width: 28px;
    height: 1px;
    flex-shrink: 0;

    background: var(--primary-color);
}

.chef-menu-bottom-info p {
    margin: 0;

    color: var(--muted-text);

    font-family: var(--font-family);
    font-size: 12px;
    font-weight: 450;
    line-height: 1.6;
}

.chef-menu-order-link {
    display: inline-flex;
    align-items: center;
    gap: 7px;

    flex-shrink: 0;

    color: var(--primary-color);

    font-family: var(--font-family);
    font-size: 12px;
    font-weight: 650;
    line-height: 1.4;
    text-decoration: none;

    transition:
        color 0.2s ease,
        transform 0.2s ease;
}

.chef-menu-order-link svg {
    transition:
        transform 0.2s ease;
}

.chef-menu-order-link:hover {
    color: var(--primary-dark);
    transform: translateX(2px);
}

.chef-menu-order-link:hover svg {
    transform: translateX(3px);
}

.chef-menu-order-link:focus-visible {
    outline: 2px solid var(--primary-color);
    outline-offset: 4px;
}


/* =========================================================
   DARK MODE
========================================================= */

body.dark-mode .chef-menu-item {
    box-shadow:
        0 9px 26px rgba(0, 0, 0, 0.18);
}

body.dark-mode .chef-menu-item:hover {
    border-color: rgba(150, 116, 215, 0.45);

    box-shadow:
        0 16px 34px rgba(0, 0, 0, 0.25);
}

body.dark-mode .chef-menu-item-favorite {
    border-color: rgba(255, 255, 255, 0.18);
    background: rgba(24, 20, 29, 0.92);
    color: var(--text-color);
}

body.dark-mode .chef-menu-item-favorite:hover {
    border-color: var(--primary-color);
    color: #FFFFFF;
}

body.dark-mode .chef-menu-item-favorite[aria-pressed="true"] {
    background: var(--primary-color);
    color: #FFFFFF;
}

body.dark-mode .chef-menu-item-type {
    background: rgba(255, 255, 255, 0.94);
}

body.dark-mode .chef-menu-add-btn:hover {
    color: #FFFFFF;
}

body.dark-mode .chef-menu-tab.active {
    color: #FFFFFF;
}


/* =========================================================
   TEXT SELECTION
========================================================= */

.chef-menu-section ::selection {
    background: var(--primary-color);
    color: #FFFFFF;
}


/* =========================================================
   REDUCED MOTION
========================================================= */

@media (prefers-reduced-motion: reduce) {

    .chef-menu-tab,
    .chef-menu-item,
    .chef-menu-item-image,
    .chef-menu-item-favorite,
    .chef-menu-add-btn,
    .chef-menu-add-btn svg,
    .chef-menu-order-link,
    .chef-menu-order-link svg {
        transition: none !important;
    }

    .chef-menu-item:hover,
    .chef-menu-item-favorite:hover,
    .chef-menu-add-btn:hover,
    .chef-menu-order-link:hover {
        transform: none;
    }

    .chef-menu-item:hover .chef-menu-item-image {
        transform: none;
    }

    .chef-menu-add-btn:hover svg,
    .chef-menu-order-link:hover svg {
        transform: none;
    }

}


/* =========================================================
   SECTION 8 — CUSTOMER REVIEWS
   PART 3 — RESPONSIVE + RTL + TOUCH + REDUCED MOTION
========================================================= */


/* =========================================================
   1439px AND BELOW
========================================================= */

@media (max-width: 1439px) {

    .chef-reviews-container {
        max-width: 1180px;
    }

    .chef-reviews-grid {
        gap: 18px;
    }

    .chef-review-card {
        padding: 20px;
    }

}


/* =========================================================
   1199px AND BELOW
========================================================= */

@media (max-width: 1199px) {

    .chef-reviews-section {
        padding: 90px 0;
    }

    .chef-reviews-container {
        max-width: 1080px;
    }

    .chef-reviews-title {
        font-size: 38px;
    }

    /* Rating summary */

    .chef-reviews-summary {
        grid-template-columns: 1fr auto 1fr;
        gap: 18px;
    }

    .chef-reviews-summary-trust {
        padding-left: 0;
    }

    .chef-reviews-summary-divider:nth-of-type(2) {
        display: none;
    }

    /* Review grid */

    .chef-reviews-grid {
        grid-template-columns: repeat(2, minmax(0, 1fr));
        gap: 20px;
    }

}


/* =========================================================
   1023px AND BELOW
========================================================= */

@media (max-width: 1023px) {

    .chef-reviews-section {
        padding: 80px 0;
    }

    .chef-reviews-container {
        max-width: 920px;
        width: min(100% - 40px, 920px);
    }

    .chef-reviews-header {
        max-width: 680px;
        margin-bottom: 38px;
    }

    .chef-reviews-title {
        font-size: 36px;
    }

    .chef-reviews-description {
        font-size: 14px;
    }

    /* Summary */

    .chef-reviews-summary {
        grid-template-columns: 1fr 1fr;
        gap: 22px;
        padding: 22px;
    }

    .chef-reviews-summary-divider {
        display: none;
    }

    .chef-reviews-summary-rating {
        padding-right: 20px;
    }

    .chef-reviews-summary-count {
        padding: 0;
    }

    .chef-reviews-summary-trust {
        grid-column: 1 / -1;

        padding-top: 18px;

        border-top: 1px solid var(--border-color);
    }

    .chef-reviews-summary-trust > div:last-child {
        flex: 1;
    }

    /* Cards */

    .chef-review-card-top {
        align-items: flex-start;
    }

}


/* =========================================================
   767px AND BELOW
========================================================= */

@media (max-width: 767px) {

    .chef-reviews-section {
        padding: 70px 0;
    }

    .chef-reviews-container {
        width: calc(100% - 40px);
    }

    /* Header */

    .chef-reviews-header {
        margin-bottom: 30px;
    }

    .chef-reviews-eyebrow {
        font-size: 11px;
        letter-spacing: 1.5px;
    }

    .chef-reviews-title {
        font-size: 31px;
        line-height: 1.22;
    }

    .chef-reviews-description {
        margin-top: 14px;
        font-size: 13px;
        line-height: 1.7;
    }

    /* Summary */

    .chef-reviews-summary {
        display: flex;
        flex-direction: column;
        align-items: stretch;
        gap: 18px;

        padding: 20px;
        margin-bottom: 28px;
    }

    .chef-reviews-summary-rating {
        justify-content: center;
        padding: 0;
    }

    .chef-reviews-rating-number {
        font-size: 36px;
    }

    .chef-reviews-rating-label {
        font-size: 11px;
    }

    .chef-reviews-summary-count {
        align-items: center;
        text-align: center;

        padding: 17px 0;

        border-top: 1px solid var(--border-color);
        border-bottom: 1px solid var(--border-color);
    }

    .chef-reviews-summary-count strong {
        font-size: 20px;
    }

    .chef-reviews-summary-trust {
        justify-content: center;
        padding: 0;
        border: 0;
    }

    /* Grid */

    .chef-reviews-grid {
        grid-template-columns: 1fr;
        gap: 16px;
    }

    .chef-review-card {
        padding: 19px;
    }

    .chef-review-card:hover {
        transform: none;
    }

    .chef-review-card-top {
        margin-bottom: 16px;
    }

    .chef-review-avatar {
        width: 44px;
        height: 44px;
        flex-basis: 44px;
    }

    .chef-review-verified {
        font-size: 9px;
    }

    .chef-review-text {
        font-size: 13px;
        line-height: 1.7;
    }

    /* Bottom */

    .chef-reviews-bottom {
        flex-direction: column;
        align-items: center;

        margin-top: 30px;
        padding-top: 21px;

        text-align: center;
    }

    .chef-reviews-bottom p {
        font-size: 12px;
    }

    .chef-reviews-all-link {
        width: 100%;
        max-width: 220px;
    }

}


/* =========================================================
   599px AND BELOW
========================================================= */

@media (max-width: 599px) {

    .chef-reviews-section {
        padding: 60px 0;
    }

    .chef-reviews-container {
        width: calc(100% - 32px);
    }

    .chef-reviews-title {
        font-size: 28px;
    }

    .chef-reviews-description {
        font-size: 12.5px;
    }

    .chef-reviews-summary {
        padding: 18px;
    }

    .chef-reviews-summary-rating {
        gap: 15px;
    }

    .chef-reviews-rating-number {
        font-size: 34px;
    }

    .chef-reviews-stars svg {
        width: 16px;
        height: 16px;
    }

    .chef-review-card {
        padding: 17px;
    }

    .chef-review-customer {
        gap: 9px;
    }

    .chef-review-avatar {
        width: 42px;
        height: 42px;
        flex-basis: 42px;
    }

    .chef-review-customer-info h3 {
        font-size: 13px;
    }

    .chef-review-customer-info span {
        font-size: 10px;
    }

    .chef-review-verified {
        padding: 5px 6px;
    }

    .chef-review-verified svg {
        width: 12px;
        height: 12px;
    }

    .chef-review-rating > span {
        font-size: 9px;
    }

    .chef-review-meal {
        font-size: 13px;
    }

    .chef-review-text {
        font-size: 12px;
    }

    .chef-review-card-bottom {
        padding-top: 17px;
    }

    .chef-review-card-bottom span {
        font-size: 8.5px;
    }

}


/* =========================================================
   479px AND BELOW
========================================================= */

@media (max-width: 479px) {

    .chef-reviews-section {
        padding: 55px 0;
    }

    .chef-reviews-container {
        width: calc(100% - 28px);
    }

    .chef-reviews-eyebrow {
        font-size: 10px;
        letter-spacing: 1.2px;
    }

    .chef-reviews-title {
        font-size: 25px;
    }

    .chef-reviews-description {
        font-size: 12px;
    }

    .chef-reviews-summary {
        padding: 16px;
        border-radius: 12px;
    }

    .chef-reviews-summary-rating {
        gap: 12px;
    }

    .chef-reviews-rating-number {
        font-size: 31px;
    }

    .chef-reviews-rating-label {
        font-size: 10px;
    }

    .chef-reviews-summary-count strong {
        font-size: 18px;
    }

    .chef-reviews-summary-count span {
        font-size: 10px;
    }

    .chef-reviews-summary-trust {
        gap: 10px;
    }

    .chef-reviews-trust-icon {
        width: 38px;
        height: 38px;
        flex-basis: 38px;
    }

    .chef-reviews-trust-icon svg {
        width: 20px;
        height: 20px;
    }

    .chef-reviews-summary-trust strong {
        font-size: 12px;
    }

    .chef-reviews-summary-trust span {
        font-size: 10px;
    }

    .chef-review-card {
        padding: 15px;
        border-radius: 11px;
    }

    .chef-review-card-top {
        gap: 8px;
    }

    .chef-review-verified span {
        display: none;
    }

    .chef-review-verified {
        width: 27px;
