/* =========================================================
   FOR CUSTOMERS — FROM SEARCH TO DELIVERY
   SECTION 3 — PART 2
========================================================= */

.customer-journey-section {
    position: relative;
    width: 100%;
    padding: 100px 0;
    background: var(--page-background);
    color: var(--text-color);
    overflow: hidden;
}

.customer-journey-container {
    width: min(1180px, calc(100% - 48px));
    margin: 0 auto;
}


/* =========================================================
   SECTION HEADER
========================================================= */

.customer-journey-header {
    max-width: 760px;
    margin: 0 auto 58px;
    text-align: center;
}

.customer-journey-eyebrow {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    min-height: 30px;
    padding: 6px 14px;
    border: 1px solid var(--border-color);
    border-radius: 999px;
    background: var(--primary-light);
    color: var(--primary-color);
    font-family: var(--font-family);
    font-size: 12px;
    font-weight: 700;
    line-height: 1;
    letter-spacing: 0.12em;
    text-transform: uppercase;
}

.customer-journey-title {
    margin: 16px 0 14px;
    color: var(--heading-color);
    font-family: var(--font-family);
    font-size: clamp(34px, 4vw, 50px);
    font-weight: 750;
    line-height: 1.12;
    letter-spacing: -0.035em;
}

.customer-journey-description {
    max-width: 690px;
    margin: 0 auto;
    color: var(--muted-text);
    font-family: var(--font-family);
    font-size: 16px;
    font-weight: 400;
    line-height: 1.75;
}


/* =========================================================
   CUSTOMER JOURNEY GRID
========================================================= */

.customer-journey-grid {
    display: grid;
    grid-template-columns: repeat(4, minmax(0, 1fr));
    gap: 22px;
}


/* =========================================================
   JOURNEY CARD
========================================================= */

.customer-journey-card {
    position: relative;
    display: flex;
    flex-direction: column;
    min-width: 0;
    min-height: 350px;
    padding: 28px 24px 26px;
    border: 1px solid var(--border-color);
    border-radius: 16px;
    background: var(--card-background);
    box-shadow: 0 10px 28px rgba(56, 32, 82, 0.06);
    overflow: hidden;
    transition:
        transform 0.25s ease,
        border-color 0.25s ease,
        box-shadow 0.25s ease;
}

.customer-journey-card:hover {
    transform: translateY(-5px);
    border-color: rgba(108, 74, 182, 0.38);
    box-shadow: 0 18px 38px rgba(56, 32, 82, 0.10);
}


/* =========================================================
   CARD TOP
========================================================= */

.customer-journey-card-top {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 16px;
    min-height: 54px;
}

.customer-journey-number {
    color: var(--primary-color);
    font-family: var(--font-family);
    font-size: 15px;
    font-weight: 750;
    line-height: 1;
    letter-spacing: 0.08em;
}

.customer-journey-icon {
    display: flex;
    align-items: center;
    justify-content: center;
    width: 52px;
    height: 52px;
    min-width: 52px;
    flex: 0 0 52px;
    border-radius: 12px;
    background: var(--primary-light);
    color: var(--primary-color);
    transition:
        background 0.25s ease,
        color 0.25s ease,
        transform 0.25s ease;
}

.customer-journey-card:hover .customer-journey-icon {
    background: var(--primary-color);
    color: #ffffff;
    transform: translateY(-2px);
}


/* =========================================================
   CARD CONTENT
========================================================= */

.customer-journey-card-content {
    margin-top: 32px;
}

.customer-journey-card-content h3 {
    margin: 0 0 12px;
    color: var(--heading-color);
    font-family: var(--font-family);
    font-size: 20px;
    font-weight: 700;
    line-height: 1.3;
    letter-spacing: -0.015em;
}

.customer-journey-card-content p {
    margin: 0;
    color: var(--muted-text);
    font-family: var(--font-family);
    font-size: 14px;
    font-weight: 400;
    line-height: 1.75;
}


/* =========================================================
   HIGHLIGHTS
========================================================= */

.customer-journey-highlights {
    display: flex;
    flex-direction: column;
    gap: 10px;
    margin: auto 0 0;
    padding: 22px 0 0;
    list-style: none;
    border-top: 1px solid var(--border-color);
}

.customer-journey-highlights li {
    display: flex;
    align-items: flex-start;
    gap: 9px;
    color: var(--text-color);
    font-family: var(--font-family);
    font-size: 13px;
    font-weight: 500;
    line-height: 1.5;
}

.customer-journey-check {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 19px;
    height: 19px;
    min-width: 19px;
    border-radius: 50%;
    background: var(--primary-light);
    color: var(--primary-color);
    font-size: 11px;
    font-weight: 800;
    line-height: 1;
}


/* =========================================================
   BOTTOM HIGHLIGHT
========================================================= */

.customer-journey-bottom {
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 14px;
    width: fit-content;
    max-width: 100%;
    margin: 46px auto 0;
    padding: 14px 22px;
    border: 1px solid var(--border-color);
    border-radius: 12px;
    background: var(--section-background);
}

.customer-journey-bottom-icon {
    display: flex;
    align-items: center;
    justify-content: center;
    width: 38px;
    height: 38px;
    min-width: 38px;
    flex: 0 0 38px;
    border-radius: 10px;
    background: var(--primary-color);
    color: #ffffff;
}

.customer-journey-bottom-content {
    display: flex;
    flex-direction: column;
    gap: 3px;
}

.customer-journey-bottom-content strong {
    color: var(--heading-color);
    font-family: var(--font-family);
    font-size: 14px;
    font-weight: 700;
    line-height: 1.4;
}

.customer-journey-bottom-content span {
    color: var(--muted-text);
    font-family: var(--font-family);
    font-size: 13px;
    font-weight: 500;
    line-height: 1.4;
}


/* =========================================================
   DARK MODE
========================================================= */

body.dark-mode .customer-journey-section {
    background: var(--page-background);
}

body.dark-mode .customer-journey-card {
    box-shadow: 0 12px 30px rgba(0, 0, 0, 0.18);
}

body.dark-mode .customer-journey-card:hover {
    box-shadow: 0 18px 38px rgba(0, 0, 0, 0.25);
}

body.dark-mode .customer-journey-bottom {
    background: var(--card-background);
}


/* =========================================================
   RTL
========================================================= */

html[dir="rtl"] .customer-journey-section,
body.rtl .customer-journey-section {
    direction: rtl;
}

html[dir="rtl"] .customer-journey-card,
body.rtl .customer-journey-card {
    direction: rtl;
}

html[dir="rtl"] .customer-journey-card-content,
body.rtl .customer-journey-card-content {
    text-align: right;
}

html[dir="rtl"] .customer-journey-highlights,
body.rtl .customer-journey-highlights {
    direction: rtl;
}

html[dir="rtl"] .customer-journey-highlights li,
body.rtl .customer-journey-highlights li {
    flex-direction: row;
}

html[dir="rtl"] .customer-journey-bottom,
body.rtl .customer-journey-bottom {
    direction: rtl;
}

html[dir="rtl"] .customer-journey-bottom-content,
body.rtl .customer-journey-bottom-content {
    text-align: right;
}


/* =========================================================
   FOCUS ACCESSIBILITY
========================================================= */

.customer-journey-card:focus-within {
    outline: 2px solid var(--primary-color);
    outline-offset: 3px;
}


/* =========================================================
   TOUCH DEVICES
========================================================= */

@media (hover: none) and (pointer: coarse) {

    .customer-journey-card:hover {
        transform: none;
        border-color: var(--border-color);
        box-shadow: 0 10px 28px rgba(56, 32, 82, 0.06);
    }

    .customer-journey-card:hover .customer-journey-icon {
        background: var(--primary-light);
        color: var(--primary-color);
        transform: none;
    }

}



